body.script:
(function () {
    var selectedInput = document.getElementById('selected_assignment_ids');
    var selectedActaInput = document.getElementById('selected_acta_numbers');
    var actionButtons = document.querySelectorAll('.js-open-action');
    var viewActaButtons = document.querySelectorAll('.js-view-acta-items');
    var menuTriggers = document.querySelectorAll('[data-menu-target]');
    var actionMenus = document.querySelectorAll('.lh_menu_list');
    var modal = document.getElementById('lh_modal_backdrop');
    var modalTitle = document.getElementById('lh_modal_title');
    var modalDesc = document.getElementById('lh_modal_desc');
    var modalTechRow = document.getElementById('lh_modal_tech_row');
    var modalTech = document.getElementById('lh_modal_technician');
    var expectedDateRow = document.getElementById('lh_modal_expected_date_row');
    var expectedDate = document.getElementById('lh_modal_expected_date');
    var extDateRow = document.getElementById('lh_modal_extension_date_row');
    var extReasonRow = document.getElementById('lh_modal_extension_reason_row');
    var extDate = document.getElementById('lh_modal_extension_date');
    var extReason = document.getElementById('lh_modal_extension_reason');
    var rejectReasonRow = document.getElementById('lh_modal_reject_reason_row');
    var rejectReason = document.getElementById('lh_modal_reject_reason');
    var returnDecisionRow = document.getElementById('lh_modal_return_decision_row');
    var returnDecision = document.getElementById('lh_modal_return_decision');
    var modalCancel = document.getElementById('lh_modal_cancel');
    var modalConfirm = document.getElementById('lh_modal_confirm');
    var actionInput = document.getElementById('action_name');
    var technicianHidden = document.getElementById('technician_id_hidden');
    var expectedReturnDateHidden = document.getElementById('expected_return_date_hidden');
    var extensionDateHidden = document.getElementById('extension_date_hidden');
    var extensionReasonHidden = document.getElementById('extension_reason_hidden');
    var rejectReasonHidden = document.getElementById('reject_reason_hidden');
    var returnDecisionHidden = document.getElementById('return_decision_hidden');
    var submitForm = document.getElementById('lh-action-form');
    var inventoryModal = document.getElementById('lh_inventory_backdrop');
    var openInventoryBtn = document.getElementById('open_inventory_modal');
    var closeInventoryBtn = document.getElementById('lh_inventory_close');
    var actaModal = document.getElementById('lh_acta_backdrop');
    var openActaBtn = document.getElementById('open_acta_modal');
    var closeActaBtn = document.getElementById('lh_acta_close');
    var actaItemsModal = document.getElementById('lh_acta_items_backdrop');
    var actaItemsTitle = document.getElementById('lh_acta_items_title');
    var actaItemsBody = document.getElementById('lh_acta_items_body');
    var closeActaItemsBtn = document.getElementById('lh_acta_items_close');
    var requestModal = document.getElementById('lh_request_backdrop');
    var requestSearch = document.getElementById('lh_request_search');
    var requestClose = document.getElementById('lh_request_close');
    var requestConfirm = document.getElementById('lh_request_confirm');
    var requestRows = document.querySelectorAll('#lh_request_list .lh_request_item');
    var techReturnModal = document.getElementById('lh_tech_return_backdrop');
    var techReturnSearch = document.getElementById('lh_tech_return_search');
    var techReturnClose = document.getElementById('lh_tech_return_close');
    var techReturnConfirm = document.getElementById('lh_tech_return_confirm');
    var techReturnRows = document.querySelectorAll('#lh_tech_return_list .lh_request_item');
    var extensionModal = document.getElementById('lh_extension_backdrop');
    var extensionSearch = document.getElementById('lh_extension_search');
    var extensionClose = document.getElementById('lh_extension_close');
    var extensionConfirm = document.getElementById('lh_extension_confirm');
    var extensionRows = document.querySelectorAll('#lh_extension_list .lh_request_item');
    var extensionDatePicker = document.getElementById('lh_extension_date_picker');
    var extensionReasonPicker = document.getElementById('lh_extension_reason_picker');
    var poolReturnModal = document.getElementById('lh_pool_return_backdrop');
    var poolReturnSearch = document.getElementById('lh_pool_return_search');
    var poolReturnClose = document.getElementById('lh_pool_return_close');
    var poolReturnConfirm = document.getElementById('lh_pool_return_confirm');
    var poolReturnRows = document.querySelectorAll('#lh_pool_return_list .lh_pool_return_row');
    var assignTechModal = document.getElementById('lh_assign_tech_backdrop');
    var assignTechSearch = document.getElementById('lh_assign_tech_search');
    var assignTechClose = document.getElementById('lh_assign_tech_close');
    var assignTechConfirm = document.getElementById('lh_assign_tech_confirm');
    var assignTechRows = document.querySelectorAll('#lh_assign_tech_list .lh_assign_tech_row');
    var assignTechTechnician = document.getElementById('lh_assign_tech_technician');
    var assignTechExpectedDate = document.getElementById('lh_assign_tech_expected_date');
    var rpModal = document.getElementById('lh_rpending_backdrop');
    var rpClose = document.getElementById('lh_rpending_close');
    var rpConfirm = document.getElementById('lh_rpending_confirm');
    var rpTabs = document.querySelectorAll('[data-rp-tab]');
    var rpPanels = {
        devoluciones: document.getElementById('lh_rp_panel_devoluciones'),
        prorrogas: document.getElementById('lh_rp_panel_prorrogas'),
        solicitudes: document.getElementById('lh_rp_panel_solicitudes')
    };
    var rpActiveTab = 'devoluciones';
    var rpExpectedWrap = document.getElementById('lh_rp_expected_wrap');
    var rpExpectedDate = document.getElementById('lh_rp_expected_date');
    var rpDecision = document.getElementById('lh_rp_decision');
    var rpRejectWrap = document.getElementById('lh_rp_reject_wrap');
    var rpRejectReason = document.getElementById('lh_rp_reject_reason');
    var pendingKindHidden = document.getElementById('pending_kind_hidden');
    var currentAction = '';
    function closeModal() {
        modal.style.display = 'none';
        currentAction = '';
    }
    function openModal(action) {
        if (action === 'assign_tech') {
            modal.style.display = 'none';
            if (assignTechSearch) assignTechSearch.value = '';
            assignTechRows.forEach(function (row) { row.style.display = ''; });
            document.querySelectorAll('.lh_assign_tech_check').forEach(function (c) { c.checked = false; });
            if (assignTechTechnician) assignTechTechnician.value = '';
            if (assignTechExpectedDate) assignTechExpectedDate.value = '';
            if (pendingKindHidden) pendingKindHidden.value = '';
            if (assignTechModal) assignTechModal.style.display = 'flex';
            return;
        }
        currentAction = action;
        actionInput.value = action;
        technicianHidden.value = '';
        expectedReturnDateHidden.value = '';
        extensionDateHidden.value = '';
        extensionReasonHidden.value = '';
        rejectReasonHidden.value = '';
        returnDecisionHidden.value = '';
        modalTech.value = '';
        expectedDate.value = '';
        extDate.value = '';
        extReason.value = '';
        rejectReason.value = '';
        returnDecision.value = 'approve';
        modalTechRow.style.display = 'none';
        expectedDateRow.style.display = 'none';
        extDateRow.style.display = 'none';
        extReasonRow.style.display = 'none';
        rejectReasonRow.style.display = 'none';
        returnDecisionRow.style.display = 'none';
        if (action === 'request_extension') {
            modalTitle.textContent = 'Solicitar prórroga';
            modalDesc.textContent = 'El técnico solicita más tiempo; el responsable podrá aprobar.';
            extDateRow.style.display = 'block';
            extReasonRow.style.display = 'block';
        } else if (action === 'tech_request_picker') {
            modal.style.display = 'none';
            actionInput.value = 'tech_request';
            if (requestModal) requestModal.style.display = 'flex';
            return;
        } else if (action === 'request_extension_picker') {
            modal.style.display = 'none';
            actionInput.value = 'request_extension';
            if (extensionModal) extensionModal.style.display = 'flex';
            return;
        } else if (action === 'tech_return_picker') {
            modal.style.display = 'none';
            actionInput.value = 'tech_return';
            if (techReturnModal) techReturnModal.style.display = 'flex';
            return;
        } else if (action === 'responsible_return_picker') {
            modal.style.display = 'none';
            actionInput.value = 'responsible_return';
            if (poolReturnModal) poolReturnModal.style.display = 'flex';
            return;
        } else if (action === 'responsible_pending_picker') {
            modal.style.display = 'none';
            actionInput.value = 'resolve_responsible_pending';
            if (rpModal) {
                rpActiveTab = 'devoluciones';
                rpTabs.forEach(function (t) {
                    t.classList.toggle('active', t.dataset.rpTab === 'devoluciones');
                });
                Object.keys(rpPanels).forEach(function (k) {
                    if (rpPanels[k]) rpPanels[k].style.display = (k === 'devoluciones') ? 'block' : 'none';
                });
                document.querySelectorAll('.lh_rp_check').forEach(function (c) { c.checked = false; });
                if (rpDecision) rpDecision.value = 'approve';
                if (rpExpectedDate) rpExpectedDate.value = '';
                if (rpRejectReason) rpRejectReason.value = '';
                rpSyncExpectedVisibility();
                rpSyncRejectVisibility();
                rpModal.style.display = 'flex';
            }
            return;
        } else {
            modalTitle.textContent = 'Operación';
            modalDesc.textContent = '';
        }
        modal.style.display = 'flex';
    }
    menuTriggers.forEach(function (btn) {
        btn.addEventListener('click', function () {
            var target = document.getElementById(btn.dataset.menuTarget);
            actionMenus.forEach(function (m) { if (m !== target) m.style.display = 'none'; });
            target.style.display = (target.style.display === 'block') ? 'none' : 'block';
        });
    });
    document.addEventListener('click', function (ev) {
        if (!ev.target.closest('.lh_menu_wrap')) {
            actionMenus.forEach(function (m) { m.style.display = 'none'; });
        }
    });
    actionButtons.forEach(function (btn) {
        btn.addEventListener('click', function () {
            actionMenus.forEach(function (m) { m.style.display = 'none'; });
            openModal(btn.dataset.action);
        });
    });
    modalCancel.addEventListener('click', closeModal);
    modal.addEventListener('click', function (ev) {
        if (ev.target === modal) closeModal();
    });
    if (openInventoryBtn) {
        openInventoryBtn.addEventListener('click', function () { inventoryModal.style.display = 'flex'; });
    }
    if (closeInventoryBtn) {
        closeInventoryBtn.addEventListener('click', function () { inventoryModal.style.display = 'none'; });
    }
    if (inventoryModal) {
        inventoryModal.addEventListener('click', function (ev) {
            if (ev.target === inventoryModal) inventoryModal.style.display = 'none';
        });
    }
    function applyActaTableFilters() {
        var df = document.getElementById('lh_acta_filter_date_from');
        var dt = document.getElementById('lh_acta_filter_date_to');
        var tech = document.getElementById('lh_acta_filter_tech');
        var fromV = (df && df.value) ? df.value : '';
        var toV = (dt && dt.value) ? dt.value : '';
        var techV = (tech && tech.value) ? tech.value : '';
        document.querySelectorAll('.lh_acta_table_row').forEach(function (tr) {
            var d = tr.getAttribute('data-filter-date') || '';
            var t = tr.getAttribute('data-filter-tech') || '';
            var ok = true;
            if ((fromV || toV) && !d) ok = false;
            if (fromV && d && d < fromV) ok = false;
            if (toV && d && d > toV) ok = false;
            if (techV && String(t) !== String(techV)) ok = false;
            tr.style.display = ok ? '' : 'none';
        });
    }
    var actaFilterFrom = document.getElementById('lh_acta_filter_date_from');
    var actaFilterTo = document.getElementById('lh_acta_filter_date_to');
    var actaFilterTech = document.getElementById('lh_acta_filter_tech');
    if (actaFilterFrom) actaFilterFrom.addEventListener('change', applyActaTableFilters);
    if (actaFilterTo) actaFilterTo.addEventListener('change', applyActaTableFilters);
    if (actaFilterTech) actaFilterTech.addEventListener('change', applyActaTableFilters);
    if (openActaBtn) {
        openActaBtn.addEventListener('click', function () {
            if (actaFilterFrom) actaFilterFrom.value = '';
            if (actaFilterTo) actaFilterTo.value = '';
            if (actaFilterTech) actaFilterTech.value = '';
            applyActaTableFilters();
            actaModal.style.display = 'flex';
        });
    }
    if (closeActaBtn) {
        closeActaBtn.addEventListener('click', function () { actaModal.style.display = 'none'; });
    }
    if (actaModal) {
        actaModal.addEventListener('click', function (ev) {
            if (ev.target === actaModal) actaModal.style.display = 'none';
        });
    }
    viewActaButtons.forEach(function (btn) {
        btn.addEventListener('click', function () {
            var acta = btn.dataset.acta || '';
            var container = btn.closest('.acta-card');
            var hidden = container ? container.querySelector('.acta-items-json') : null;
            var items = [];
            try {
                items = JSON.parse((hidden && hidden.dataset.items) || '[]');
            } catch (err) {
                items = [];
            }
            actaItemsTitle.textContent = 'Detalle acta: ' + acta;
            actaItemsBody.innerHTML = '';
            items.forEach(function (it) {
                var tr = document.createElement('tr');
                tr.innerHTML = '' + (it.serial || '') + '' + (it.product || '') + '' + (it.state_label || it.state || '') + '';
                actaItemsBody.appendChild(tr);
            });
            if (!items.length) {
                var tr = document.createElement('tr');
                tr.innerHTML = 'Sin ítems para mostrar';
                actaItemsBody.appendChild(tr);
            }
            actaItemsModal.style.display = 'flex';
        });
    });
    if (closeActaItemsBtn) {
        closeActaItemsBtn.addEventListener('click', function () { actaItemsModal.style.display = 'none'; });
    }
    if (actaItemsModal) {
        actaItemsModal.addEventListener('click', function (ev) {
            if (ev.target === actaItemsModal) actaItemsModal.style.display = 'none';
        });
    }
    if (requestSearch) {
        requestSearch.addEventListener('input', function () {
            var q = (requestSearch.value || '').toLowerCase().trim();
            requestRows.forEach(function (row) {
                var text = (row.dataset.search || '');
                row.style.display = (!q || text.indexOf(q) !== -1) ? '' : 'none';
            });
        });
    }
    if (requestClose) {
        requestClose.addEventListener('click', function () { requestModal.style.display = 'none'; });
    }
    if (requestModal) {
        requestModal.addEventListener('click', function (ev) {
            if (ev.target === requestModal) requestModal.style.display = 'none';
        });
    }
    if (requestConfirm) {
        requestConfirm.addEventListener('click', function () {
            var ids = [];
            document.querySelectorAll('.lh_request_check:checked').forEach(function (c) { ids.push(c.value); });
            if (!ids.length) {
                alert('Seleccione al menos un activo disponible para solicitar.');
                return;
            }
            selectedInput.value = ids.join(',');
            selectedActaInput.value = '';
            actionInput.value = 'tech_request';
            submitForm.submit();
        });
    }
    if (techReturnSearch) {
        techReturnSearch.addEventListener('input', function () {
            var q = (techReturnSearch.value || '').toLowerCase().trim();
            techReturnRows.forEach(function (row) {
                var text = (row.dataset.search || '');
                row.style.display = (!q || text.indexOf(q) !== -1) ? '' : 'none';
            });
        });
    }
    if (techReturnClose) {
        techReturnClose.addEventListener('click', function () { techReturnModal.style.display = 'none'; });
    }
    if (techReturnModal) {
        techReturnModal.addEventListener('click', function (ev) {
            if (ev.target === techReturnModal) techReturnModal.style.display = 'none';
        });
    }
    if (techReturnConfirm) {
        techReturnConfirm.addEventListener('click', function () {
            var actas = [];
            document.querySelectorAll('.lh_tech_return_check:checked').forEach(function (c) { actas.push(c.value); });
            if (!actas.length) {
                alert('Seleccione al menos un acta para solicitar devolucion.');
                return;
            }
            selectedInput.value = '';
            selectedActaInput.value = actas.join(',');
            actionInput.value = 'tech_return';
            submitForm.submit();
        });
    }
    if (extensionSearch) {
        extensionSearch.addEventListener('input', function () {
            var q = (extensionSearch.value || '').toLowerCase().trim();
            extensionRows.forEach(function (row) {
                var text = (row.dataset.search || '');
                row.style.display = (!q || text.indexOf(q) !== -1) ? '' : 'none';
            });
        });
    }
    if (extensionClose) {
        extensionClose.addEventListener('click', function () { extensionModal.style.display = 'none'; });
    }
    if (extensionModal) {
        extensionModal.addEventListener('click', function (ev) {
            if (ev.target === extensionModal) extensionModal.style.display = 'none';
        });
    }
    if (extensionConfirm) {
        extensionConfirm.addEventListener('click', function () {
            var actas = [];
            document.querySelectorAll('.lh_extension_check:checked').forEach(function (c) { actas.push(c.value); });
            if (!actas.length) {
                alert('Seleccione al menos un acta para solicitar prórroga.');
                return;
            }
            if (!extensionDatePicker.value) {
                alert('Debe indicar una fecha de prórroga.');
                return;
            }
            selectedInput.value = '';
            selectedActaInput.value = actas.join(',');
            actionInput.value = 'request_extension';
            extensionDateHidden.value = extensionDatePicker.value;
            extensionReasonHidden.value = (extensionReasonPicker.value || '').trim();
            submitForm.submit();
        });
    }
    function rpSyncExpectedVisibility() {
        if (!rpExpectedWrap) return;
        rpExpectedWrap.style.display = (rpActiveTab === 'solicitudes') ? 'block' : 'none';
    }
    function rpSyncRejectVisibility() {
        if (!rpRejectWrap || !rpDecision) return;
        rpRejectWrap.style.display = (rpDecision.value === 'reject') ? 'block' : 'none';
    }
    if (rpTabs.length) {
        rpTabs.forEach(function (tab) {
            tab.addEventListener('click', function () {
                rpActiveTab = tab.dataset.rpTab || 'devoluciones';
                rpTabs.forEach(function (t) { t.classList.toggle('active', t === tab); });
                Object.keys(rpPanels).forEach(function (k) {
                    if (rpPanels[k]) rpPanels[k].style.display = (k === rpActiveTab) ? 'block' : 'none';
                });
                rpSyncExpectedVisibility();
            });
        });
    }
    if (rpDecision) {
        rpDecision.addEventListener('change', rpSyncRejectVisibility);
    }
    if (rpClose) {
        rpClose.addEventListener('click', function () { if (rpModal) rpModal.style.display = 'none'; });
    }
    if (rpModal) {
        rpModal.addEventListener('click', function (ev) {
            if (ev.target === rpModal) rpModal.style.display = 'none';
        });
    }
    if (rpConfirm) {
        rpConfirm.addEventListener('click', function () {
            var kindMap = { devoluciones: 'return', prorrogas: 'extension', solicitudes: 'request' };
            var kind = kindMap[rpActiveTab] || 'return';
            var panel = rpPanels[rpActiveTab];
            if (!panel) return;
            var actas = [];
            panel.querySelectorAll('.lh_rp_check:checked').forEach(function (c) { actas.push(c.value); });
            if (!actas.length) {
                alert('Seleccione al menos un acta en la pestaña activa.');
                return;
            }
            if (rpActiveTab === 'solicitudes' && rpDecision.value === 'approve' && rpExpectedDate && !rpExpectedDate.value) {
                alert('Indique fecha estimada de devolución para aprobar la solicitud.');
                return;
            }
            if (pendingKindHidden) pendingKindHidden.value = kind;
            selectedActaInput.value = actas.join(',');
            selectedInput.value = '';
            returnDecisionHidden.value = rpDecision.value || 'approve';
            expectedReturnDateHidden.value = (rpActiveTab === 'solicitudes' && rpDecision.value === 'approve' && rpExpectedDate) ? rpExpectedDate.value : '';
            rejectReasonHidden.value = (rpDecision.value === 'reject' && rpRejectReason) ? (rpRejectReason.value || '') : '';
            actionInput.value = 'resolve_responsible_pending';
            if (rpModal) rpModal.style.display = 'none';
            submitForm.submit();
        });
    }
    [['lh_rp_search_devoluciones', 'lh_rp_panel_devoluciones'], ['lh_rp_search_prorrogas', 'lh_rp_panel_prorrogas'], ['lh_rp_search_solicitudes', 'lh_rp_panel_solicitudes']].forEach(function (pair) {
        var inp = document.getElementById(pair[0]);
        var panel = document.getElementById(pair[1]);
        if (inp && panel) {
            inp.addEventListener('input', function () {
                var q = (inp.value || '').toLowerCase().trim();
                panel.querySelectorAll('.lh_rp_acta_row').forEach(function (row) {
                    var text = (row.dataset.search || '');
                    row.style.display = (!q || text.indexOf(q) !== -1) ? '' : 'none';
                });
            });
        }
    });
    if (assignTechSearch) {
        assignTechSearch.addEventListener('input', function () {
            var q = (assignTechSearch.value || '').toLowerCase().trim();
            assignTechRows.forEach(function (row) {
                var text = (row.dataset.search || '');
                row.style.display = (!q || text.indexOf(q) !== -1) ? '' : 'none';
            });
        });
    }
    if (assignTechClose) {
        assignTechClose.addEventListener('click', function () { if (assignTechModal) assignTechModal.style.display = 'none'; });
    }
    if (assignTechModal) {
        assignTechModal.addEventListener('click', function (ev) {
            if (ev.target === assignTechModal) assignTechModal.style.display = 'none';
        });
    }
    if (assignTechConfirm) {
        assignTechConfirm.addEventListener('click', function () {
            var ids = [];
            document.querySelectorAll('.lh_assign_tech_check:checked').forEach(function (c) { ids.push(c.value); });
            if (!ids.length) {
                alert('Seleccione al menos un activo en pool laboratorio.');
                return;
            }
            if (!assignTechTechnician || !assignTechTechnician.value) {
                alert('Debe seleccionar un técnico.');
                return;
            }
            if (!assignTechExpectedDate || !assignTechExpectedDate.value) {
                alert('Debe indicar fecha estimada de devolución.');
                return;
            }
            selectedInput.value = ids.join(',');
            selectedActaInput.value = '';
            technicianHidden.value = assignTechTechnician.value;
            expectedReturnDateHidden.value = assignTechExpectedDate.value;
            if (pendingKindHidden) pendingKindHidden.value = '';
            actionInput.value = 'assign_tech';
            if (assignTechModal) assignTechModal.style.display = 'none';
            submitForm.submit();
        });
    }
    if (poolReturnSearch) {
        poolReturnSearch.addEventListener('input', function () {
            var q = (poolReturnSearch.value || '').toLowerCase().trim();
            poolReturnRows.forEach(function (row) {
                var text = (row.dataset.search || '');
                row.style.display = (!q || text.indexOf(q) !== -1) ? '' : 'none';
            });
        });
    }
    if (poolReturnClose) {
        poolReturnClose.addEventListener('click', function () { if (poolReturnModal) poolReturnModal.style.display = 'none'; });
    }
    if (poolReturnModal) {
        poolReturnModal.addEventListener('click', function (ev) {
            if (ev.target === poolReturnModal) poolReturnModal.style.display = 'none';
        });
    }
    if (poolReturnConfirm) {
        poolReturnConfirm.addEventListener('click', function () {
            var ids = [];
            document.querySelectorAll('.lh_pool_return_check:checked').for
